(()=>{const art=()=>{let h=document.querySelector(".hero");if(h&&!h.querySelector(".hero-art"))h.insertAdjacentHTML("beforeend",'<img class="hero-art" src="assets/img/hero-estudiantes.png" alt="" aria-hidden="true">');let b=document.querySelector(".explore-banner");if(b&&!b.querySelector(".explore-art"))b.insertAdjacentHTML("beforeend",'<img class="explore-art" src="assets/img/explorar-ruta.png" alt="" aria-hidden="true">');document.querySelectorAll(".form-box,.profile-box,.detail,.empty").forEach(x=>{if(!x.querySelector(".section-art"))x.insertAdjacentHTML("beforeend",'<img class="section-art" src="assets/img/kit-creativo.png" alt="" aria-hidden="true">')})};new MutationObserver(art).observe(document.body,{childList:true,subtree:true});art()})();
